import sys


def check_digit(digits):
    total = 0
    for i, ch in enumerate(digits):
        if i % 2 == 0:
            total += int(ch) * 3
        else:
            total += int(ch)
    return 10 - total % 10


def fmt(digits):
    return f"{digits[0:3]}.{digits[3:7]}.{digits[7:11]}.{digits[11:13]}"


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        digits = line.replace(".", "").replace(" ", "")
        if len(digits) != 13 and len(digits) != 12:
            print("ERROR")
            continue
        if len(digits) == 13:
            if digits.startswith("756"):
                if check_digit(digits[:12]) == int(digits[12]):
                    print("VALID", fmt(digits))
                else:
                    print("INVALID", check_digit(digits[:12]))
            else:
                print("ERROR")
        elif len(digits) == 12:
            if digits.startswith("756"):
                print("COMPLETE", fmt(digits + str(check_digit(digits))))
            else:
                print("ERROR")


if __name__ == "__main__":
    main()
